import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Planificación Académica: Proyecto Sociotecnológico III (Trimestre VIII)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-VIII.md","filePath":"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-VIII.md"}'),r={name:"materias/Proyecto_Sociotecnologico_III/Planificacion_Trimestre_III-VIII.md"};function n(d,e,s,l,c,u){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="planificacion-academica-proyecto-sociotecnologico-iii-trimestre-viii" tabindex="-1">Planificación Académica: Proyecto Sociotecnológico III (Trimestre VIII) <a class="header-anchor" href="#planificacion-academica-proyecto-sociotecnologico-iii-trimestre-viii" aria-label="Permalink to &quot;Planificación Académica: Proyecto Sociotecnológico III (Trimestre VIII)&quot;">​</a></h1><p>En este trimestre se ejecuta la fase intensiva de ingeniería de software: selección y aplicación rigurosa de la metodología de desarrollo, diseño arquitectónico del sistema, modelado de procesos y datos, y codificación de los módulos principales de la solución informática.</p><hr><h2 id="📅-trimestre-viii-metodologia-arquitectura-y-desarrollo-del-sistema-unidad-4" tabindex="-1">📅 Trimestre VIII: Metodología, Arquitectura y Desarrollo del Sistema (Unidad 4) <a class="header-anchor" href="#📅-trimestre-viii-metodologia-arquitectura-y-desarrollo-del-sistema-unidad-4" aria-label="Permalink to &quot;📅 Trimestre VIII: Metodología, Arquitectura y Desarrollo del Sistema (Unidad 4)&quot;">​</a></h2><h3 id="📝-evaluacion-1-metodologias-de-desarrollo-de-software-unidad-4" tabindex="-1">📝 Evaluación 1: Metodologías de Desarrollo de Software (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-1-metodologias-de-desarrollo-de-software-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 1: Metodologías de Desarrollo de Software (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Seleccionar, comparar y aplicar la metodología de desarrollo adecuada para sistemas distribuidos o de gestión empresarial/pública.</p><ul><li>Metodologías Tradicionales (RUP, Cascada) vs. Metodologías Ágiles (Scrum, XP, Kanban).</li><li>Metodologías de Software Libre en Venezuela (MERINDE, WATCH).</li><li>Adaptación del ciclo de vida a las necesidades de la institución u organización socioproductiva.</li><li><strong>Actividad:</strong> <strong>Justificación Metodológica y Plan de Sprints/Fases.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-diseno-arquitectonico-y-modelado-orientado-a-objetos-unidad-4" tabindex="-1">📝 Evaluación 2: Diseño Arquitectónico y Modelado Orientado a Objetos (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-2-diseno-arquitectonico-y-modelado-orientado-a-objetos-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 2: Diseño Arquitectónico y Modelado Orientado a Objetos (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Modelar formalmente la arquitectura y el comportamiento del sistema mediante estándares UML.</p><ul><li>Patrones arquitectónicos: Modelo-Vista-Controlador (MVC), Arquitecturas Multicapas y Servicios Web / REST APIs.</li><li>Modelado funcional y dinámico: Diagramas de Casos de Uso, Diagramas de Actividades y Diagramas de Secuencia.</li><li>Modelado estructural: Diagramas de Clases, Diagramas de Paquetes y Diagramas de Componentes.</li><li><strong>Actividad:</strong> <strong>Dossier de Modelado Arquitectónico UML.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-diseno-de-base-de-datos-y-persistencia-de-alto-rendimiento-unidad-4" tabindex="-1">📝 Evaluación 3: Diseño de Base de Datos y Persistencia de Alto Rendimiento (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-3-diseno-de-base-de-datos-y-persistencia-de-alto-rendimiento-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 3: Diseño de Base de Datos y Persistencia de Alto Rendimiento (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Diseñar el modelo relacional de datos optimizado para consultas complejas y alta concurrencia.</p><ul><li>Modelo Entidad-Relación y Modelo Relacional normalizado (3FN / BCNF).</li><li>Diccionario de datos exhaustivo, índices, vistas, procedimientos almacenados y disparadores (<em>triggers</em>).</li><li>Implementación en SGBD libre (PostgreSQL / MariaDB) garantizando integridad referencial y atomicidad (ACID).</li><li><strong>Actividad:</strong> <strong>Defensa del Modelo de Datos y Scripts DDL/DML.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-construccion-y-demostracion-del-prototipo-funcional-unidad-4" tabindex="-1">📝 Evaluación 4: Construcción y Demostración del Prototipo Funcional (Unidad 4) <a class="header-anchor" href="#📝-evaluacion-4-construccion-y-demostracion-del-prototipo-funcional-unidad-4" aria-label="Permalink to &quot;📝 Evaluación 4: Construcción y Demostración del Prototipo Funcional (Unidad 4)&quot;">​</a></h3><p><strong>Objetivo:</strong> Implementar los módulos nucleares de la aplicación y presentar la demostración en vivo.</p><ul><li>Codificación en lenguajes libres modernos con estándares de código limpio y control de versiones con Git.</li><li>Módulos transaccionales, control de acceso basado en roles (RBAC) y reportes estadísticos.</li><li>Demostración operativa en vivo ante el jurado evaluador institucional.</li><li><strong>Actividad:</strong> <strong>2do Informe de Avance (Afinar) y Prototipo en Vivo.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Al finalizar el Trimestre VIII, el proyecto cuenta con su diseño técnico consolidado, su base de datos implementada y un prototipo funcional operativo que satisface los requerimientos prioritarios de la organización, preparado para la fase de optimización, pruebas e implantación en el trimestre final.</p>',19)])])}const I=a(r,[["render",n]]);export{p as __pageData,I as default};
